              </Button>
            )}
          </div>
          {doc && (
            <form
              style={{ marginTop: 12 }}
              onSubmit={(e) => {
                e.preventDefault();
                void save();
              }}
            >
              <DocumentFields value={doc} onChange={setDoc} />
              {error && (
                <p className="form-error" role="alert">
                  {error}
                </p>
