        <button
          className="toast-action"
          onClick={() => {
            notice.action!.run();
            onClose();
          }}
        >
          {notice.action.label}
        </button>
      )}
      <button onClick={onClose} aria-label="Cerrar aviso">
        <X size={18} />
      </button>
    </div>
  );
