          notice={error}
          onClose={() => setError(closeOwn(error.id))}
        />
      )}
      {info && (
        <Toast
          key={info.id}
          notice={info}
          stacked={!!error}
          onClose={() => setInfo(closeOwn(info.id))}
        />
      )}
    </>
  );
