export function QueryState({
  query,
  children,
  english = false,
}: {
  query: any;
  children: ReactNode;
  english?: boolean;
}) {
  // 05-M3: sin conexión React Query deja en pausa las consultas al servidor:
  // antes quedaba «Cargando datos…» para siempre.
  if (query.isPending && query.fetchStatus === "paused")
    return (
      <div className="error-panel" role="status">
        <WifiOff />
        <p>{english ? "Offline: this information needs an internet connection." : "Sin conexión: esta información necesita internet."}</p>
        <Button variant="secondary" onClick={() => query.refetch()}>
          {english ? "Retry" : "Reintentar"}
        </Button>
      </div>
    );
  if (query.isPending) return <Loading label={english ? "Loading data…" : undefined} />;
  if (query.error)
    return (
      <div className="error-panel" role="alert">
        <AlertCircle />
        <p>{english ? (query.error?.status === 401 ? "Your session ended. Sign in again to continue." : query.error?.status === 403 ? "You do not have access to this information. Ask management for help." : "We could not load this information. Check your connection and retry.") : managementQueryError(query.error)}</p>
        <Button variant="secondary" onClick={() => query.refetch()}>
          {english ? "Retry" : "Reintentar"}
        </Button>
      </div>
    );
  return <>{children}</>;
}
export type Field = {
  key: string;
  label: string;
  type?:
    | "text"
    | "number"
    | "date"
    | "email"
    | "password"
    | "select"
    | "checkbox"
    | "textarea";
  options?: { label: string; value: string }[];
  required?: boolean;
  initial?: string | number | boolean;
  min?: number;
  max?: number;
  step?: string;
  inputMode?: React.HTMLAttributes<HTMLInputElement>["inputMode"];
  minLength?: number;
  maxLength?: number;
  pattern?: string;
  title?: string;
  resetFieldsOnChange?: string[];
  help?: string;
};
// 03-A1: aviso corto al pedir los datos de un cliente. El texto jurídico
// completo lo redacta la tienda con su abogado; /privacidad.html es el resumen.
export function CustomerPrivacyNotice() {
  return (
    <p className="privacy-notice full">
      Usamos estos datos sólo para registrar las ventas, garantías y créditos
      del cliente. Teléfono, correo y cédula/RNC son opcionales. El cliente
      puede pedir verlos, corregirlos o borrarlos.{" "}
      <a href="/privacidad.html" target="_blank" rel="noopener">
        Privacidad
      </a>
    </p>
  );
}
export function FormModal({
  title,
  english = false,
  fields,
  onSubmit,
  onClose,
  initial = {},
  notice,
  onFieldChange,
}: {
  title: string;
  english?: boolean;
  fields: Field[] | ((values: Record<string, any>) => Field[]);
  onSubmit: (data: Record<string, any>) => Promise<unknown>;
  onClose: () => void;
  initial?: Record<string, any>;
  notice?: ReactNode;
  onFieldChange?: (
    key: string,
    value: any,
    values: Record<string, any>,
  ) => Record<string, any> | void;
}) {
  const initialFields = typeof fields === "function" ? fields(initial) : fields;
  const [values, setValues] = useState<Record<string, any>>(() =>
    Object.fromEntries(
      initialFields.map((f) => [
        f.key,
        initial[f.key] ?? f.initial ?? (f.type === "checkbox" ? false : ""),
      ]),
    ),
  );
  const [busy, setBusy] = useState(false),
    [error, setError] = useState("");
  const client = useQueryClient();
  const resolvedFields = typeof fields === "function" ? fields(values) : fields;
  function changeField(key: string, value: any, resetFields: string[] = []) {
    setValues((current) => {
      const next = {
        ...current,
        [key]: value,
        ...Object.fromEntries(resetFields.map((reset) => [reset, ""])),
      };
      return onFieldChange?.(key, value, next) ?? next;
    });
  }
  async function submit(event: React.FormEvent) {
    event.preventDefault();
    setBusy(true);
    setError("");
    try {
      const data = { ...values };
      for (const f of resolvedFields)
        if (f.type === "number") data[f.key] = Number(data[f.key]);
      await onSubmit(data);
      await client.invalidateQueries();
      toast(english ? "Changes saved." : "Cambios guardados.");
      onClose();
    } catch (e: any) {
      setError(businessErrorMessage(e));
    } finally {
      setBusy(false);
    }
  }
  return (
    <Modal open onClose={onClose} title={title} closeLabel={english ? "Close" : "Cerrar"}>
      <form onSubmit={submit} className="form-grid">
        {resolvedFields.map((f) => (
          <label
            className={`field ${f.type === "textarea" ? "full" : ""}`}
            key={f.key}
          >
            <span>
              {f.label}
              {f.required ? " *" : ""}
            </span>
            {f.type === "select" ? (
              <select
                required={f.required}
                value={values[f.key]}
                onChange={(e) =>
                  changeField(f.key, e.target.value, f.resetFieldsOnChange)
                }
              >
                <option value="">{english ? "Select…" : "Seleccionar…"}</option>
                {f.options?.map((o) => (
                  <option key={o.value} value={o.value}>
                    {o.label}
                  </option>
                ))}
              </select>
            ) : f.type === "checkbox" ? (
              <input
                type="checkbox"
                checked={values[f.key]}
                onChange={(e) => changeField(f.key, e.target.checked)}
              />
            ) : f.type === "textarea" ? (
              <textarea
                required={f.required}
                value={values[f.key]}
                onChange={(e) => changeField(f.key, e.target.value)}
              />
            ) : (
              <input
                required={f.required}
                type={f.type || "text"}
                min={f.min}
                max={f.max}
                minLength={f.minLength}
                maxLength={f.maxLength}
                inputMode={f.inputMode}
                pattern={f.pattern}
                title={f.title}
                step={f.step || (f.type === "number" ? "0.01" : undefined)}
                value={values[f.key]}
                onChange={(e) => changeField(f.key, e.target.value)}
              />
            )}
            <small>{f.help}</small>
          </label>
        ))}
        {notice}
        {error && (
          <p className="form-error full" role="alert">
            {english && error === businessErrorMessage(null)
              ? "We could not complete the operation. Check the information and your connection, then try again. If it continues, ask management for help."
              : error}
          </p>
        )}
        <div className="modal-footer full">
          <Button type="button" variant="secondary" onClick={onClose}>
            {english ? "Cancel" : "Cancelar"}
          </Button>
          <Button disabled={busy}>
            {busy
              ? english
                ? "Saving…"
                : "Guardando…"
              : english
                ? "Save"
                : "Guardar"}
          </Button>
        </div>
      </form>
    </Modal>
  );
}
export function ConfirmModal({
  title,
  english = false,
  description,
  confirmLabel = "Confirmar",
  onConfirm,
  onClose,
}: {
  title: string;
  english?: boolean;
  description: string;
  confirmLabel?: string;
  onConfirm: (reason: string) => Promise<void>;
  onClose: () => void;
}) {
  const [reason, setReason] = useState(""),
    [busy, setBusy] = useState(false),
    [error, setError] = useState("");
  return (
    <Modal open title={title} onClose={onClose}>
      <p>{description}</p>
      <form
        onSubmit={async (e) => {
          e.preventDefault();
          setBusy(true);
          try {
            await onConfirm(reason);
            onClose();
          } catch (e: any) {
            setError(businessErrorMessage(e));
            setBusy(false);
          }
        }}
      >
        <label className="field">
          <span>{english ? "Reason required" : "Motivo obligatorio"}</span>
          <textarea
            minLength={3}
            required
            value={reason}
            onChange={(e) => setReason(e.target.value)}
          />
        </label>
        {error && <p className="form-error">{error}</p>}
        <div className="modal-footer">
          <Button type="button" variant="secondary" onClick={onClose}>
            {english ? "Cancel" : "Cancelar"}
          </Button>
          <Button variant="danger" disabled={busy}>
            {busy ? (english ? "Processing…" : "Procesando…") : confirmLabel}
          </Button>
        </div>
      </form>
    </Modal>
  );
}
export async function mutate(path: string, data: unknown, method = "POST") {
  return api(path, { method, body: JSON.stringify(data) });
}

// Búsqueda de la caja: sin acentos, sin mayúsculas y por palabras sueltas.
const fold = (value: string) =>
  value
    .replace(/['’´`ʼ‘]/g, "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase();
// Palabra por palabra, con sinónimos y unidades (shared: matchesSearch).
export const searchWords = (query: string) =>
  searchTerms(query).map((alts) => alts.join("|"));
export const matchesWords = (text: string, words: string[]) =>
  words.every((w) => matchesSearch(text, w.split("|")[0]));
// Imagen genérica por categoría cuando el producto no tiene foto.
export const categoryImage = (category = "") => {
  const c = fold(category);
  if (c.includes("suplement")) return "/products/supplements.svg";
  if (c.includes("maquill")) return "/products/makeup.svg";
  if (c.includes("faja")) return "/products/shapewear.svg";
  if (c.includes("ropa")) return "/products/clothing.svg";
  return "/products/accessories.svg";
};

